    internal class TierConverter : JsonConverter
    {
        public override bool CanConvert(Type t) => t == typeof(Tier) || t == typeof(Tier?);

        public override object ReadJson(JsonReader reader, Type t, object existingValue, JsonSerializer serializer)
        {
            if (reader.TokenType == JsonToken.Null) return null;
            var value = serializer.Deserialize<string>(reader);
            switch (value)
            {
                case "learner":
                    return Tier.Learner;
                case "regular":
                    return Tier.Regular;
                case "ustad":
                    return Tier.Ustad;
            }
            throw new Exception("Cannot unmarshal type Tier");
        }

        public override void WriteJson(JsonWriter writer, object untypedValue, JsonSerializer serializer)
        {
            if (untypedValue == null)
            {
                serializer.Serialize(writer, null);
                return;
            }
            var value = (Tier)untypedValue;
            switch (value)
            {
                case Tier.Learner:
                    serializer.Serialize(writer, "learner");
                    return;
                case Tier.Regular:
                    serializer.Serialize(writer, "regular");
                    return;
                case Tier.Ustad:
                    serializer.Serialize(writer, "ustad");
                    return;
            }
            throw new Exception("Cannot marshal type Tier");
        }

        public static readonly TierConverter Singleton = new TierConverter();
    }

    internal class PurpleMinMaxLengthCheckConverter : JsonConverter
    {
        public override bool CanConvert(Type t) => t == typeof(string);

        public override object ReadJson(JsonReader reader, Type t, object existingValue, JsonSerializer serializer)
        {
            var value = serializer.Deserialize<string>(reader);
            if (value.Length <= 140)
            {
                return value;
            }
            throw new Exception("Cannot unmarshal type string");
        }

        public override void WriteJson(JsonWriter writer, object untypedValue, JsonSerializer serializer)
        {
            var value = (string)untypedValue;
            if (value.Length <= 140)
            {
                serializer.Serialize(writer, value);
                return;
            }
            throw new Exception("Cannot marshal type string");
        }

        public static readonly PurpleMinMaxLengthCheckConverter Singleton = new PurpleMinMaxLengthCheckConverter();
    }

